import { Component } from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';

@Component({
  selector: 'wgj-videos',
  templateUrl: './videos.component.html',
  styleUrls: ['./videos.component.scss'],
})
export class VideosComponent {
  videos = [
    {
      title: 'Women Game Jam 2020 Keynote',
      url: this.sanitizer.bypassSecurityTrustResourceUrl(
        'https://www.youtube.com/embed/spBRwNSl5_0',
      ),
    },
    {
      title: 'Meetup Press Start 2023',
      url: this.sanitizer.bypassSecurityTrustResourceUrl(
        'https://www.youtube.com/embed/eXTlzyO9lUY',
      ),
    },
  ];

  constructor(private sanitizer: DomSanitizer) {}
}
<div class="container">
  <div class="videos">
    <img class="videos__cloud" src="assets/img/cloud.png" alt="nube pixelada" />
    <wgj-section-title data-aos="fade-up">
      Videos de Eventos Previos
    </wgj-section-title>
    <div class="videos__content">
      <iframe
        *ngFor="let video of videos"
        data-aos="fade-up"
        width="500"
        height="280"
        frameborder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowfullscreen
        [src]="video.url"
        [title]="video.title"
      ></iframe>
    </div>
  </div>
</div>
